#include <iostream>
#include <sstream>
#include <iterator>
#include <vector>
#include <numeric>

int main() {
    // Simulate input stream with two integers: 12 and 25
    std::istringstream input_source("12 25");
    std::istream_iterator<int> input_int(input_source);

    int number1 = *input_int;
    ++input_int;
    int number2 = *input_int;

    // Output sum using ostream_iterator
    std::cout << "Sum: ";
    std::ostream_iterator<int> output_int(std::cout);
    *output_int = number1 + number2;
    std::cout << "\n";

    // Demonstration of random-access jumping
    std::vector<int> vec = {10, 20, 30, 40, 50};
    auto it = vec.begin();
    it += 3; // Jump forward 3 elements in O(1)
    std::cout << "Element at offset 3: " << *it << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <list>

int main() {
    std::vector<int> vec = {10, 20, 30, 40, 50};
    std::list<int> lst = {100, 200, 300};

    // 1. Const reverse iterator on vector (read-only backward)
    std::cout << "Vector reverse: ";
    for (auto crit = vec.crbegin(); crit != vec.crend(); ++crit) {
        std::cout << *crit << ' ';
    }
    std::cout << "\n";

    // 2. Random access arithmetic on vector iterators
    auto it1 = vec.cbegin();
    auto it2 = it1 + 4; // p + i
    std::cout << "Distance it2 - it1: " << (it2 - it1) << "\n";
    std::cout << "Subscript it1[2]: " << it1[2] << "\n";
    std::cout << "Is it1 < it2? " << (it1 < it2 ? "true" : "false") << "\n";

    // 3. Bidirectional iterator on list (only ++ and --)
    auto list_it = lst.end();
    --list_it; // Step backward to last element
    std::cout << "Last element of list: " << *list_it << "\n";

    return 0;
}

#include <iostream>
#include <vector>
#include <deque>
#include <algorithm>
#include <iterator>

int main() {
    // Vector dynamic sequence
    std::vector<int> numbers = {5, 3, 8, 1, 9};

    // Using std::copy algorithm with ostream_iterator
    std::cout << "Original vector: ";
    std::copy(numbers.begin(), numbers.end(),
              std::ostream_iterator<int>(std::cout, " "));
    std::cout << "\n";

    // Sort vector using random access iterators
    std::sort(numbers.begin(), numbers.end());
    std::cout << "Sorted vector: ";
    std::copy(numbers.begin(), numbers.end(),
              std::ostream_iterator<int>(std::cout, " "));
    std::cout << "\n";

    // Deque: fast insertion at both ends
    std::deque<int> deq;
    deq.push_back(100);  // insert back
    deq.push_front(50);  // insert front
    deq.push_back(150);

    std::cout << "Deque contents: ";
    std::copy(deq.begin(), deq.end(),
              std::ostream_iterator<int>(std::cout, " "));
    std::cout << "\n";

    return 0;
}
